package com.github.L_Ender.cataclysm.util;

import net.minecraft.tags.TagKey;
import net.minecraftforge.common.util.Lazy;
import net.minecraftforge.registries.IForgeRegistry;
import net.minecraftforge.registries.tags.ITag;
import net.minecraftforge.registries.tags.ITagManager;

public record LazyTagLookup<TYPE>(TagKey<TYPE> key, Lazy<ITag<TYPE>> lazyTag) {
    public static <TYPE> LazyTagLookup<TYPE> create(IForgeRegistry<TYPE> registry, TagKey<TYPE> key) {
        return new LazyTagLookup<TYPE>(key, Lazy.of(() -> LazyTagLookup.manager(registry).getTag(key)));
    }

    public ITag<TYPE> tag() {
        return (ITag)this.lazyTag.get();
    }

    public boolean contains(TYPE element) {
        return this.tag().contains(element);
    }

    public boolean isEmpty() {
        return this.tag().isEmpty();
    }

    public static <TYPE> ITagManager<TYPE> manager(IForgeRegistry<TYPE> registry) {
        ITagManager tags = registry.tags();
        if (tags == null) {
            throw new IllegalStateException("Expected " + String.valueOf(registry.getRegistryName()) + " to have tags.");
        }
        return tags;
    }
}

